sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    /*
     * ============================================================
     * CHOICE HELPERS
     * ============================================================
     */

    function getChoiceValueByLabel(
        tableName,
        fieldName,
        label
    ) {

        var choice =
            new GlideRecord('sys_choice');

        choice.addQuery(
            'name',
            tableName
        );

        choice.addQuery(
            'element',
            fieldName
        );

        choice.addQuery(
            'label',
            label
        );

        choice.addQuery(
            'inactive',
            false
        );

        choice.setLimit(1);
        choice.query();

        if (choice.next()) {

            return String(
                choice.getValue('value')
            );
        }

        return '';
    }


    function setChoiceByLabel(
        gr,
        fieldName,
        label
    ) {

        if (
            !gr ||
            !gr.isValidField(fieldName)
        ) {
            return false;
        }

        var value =
            getChoiceValueByLabel(
                gr.getTableName(),
                fieldName,
                label
            );

        if (!value) {
            return false;
        }

        gr.setValue(
            fieldName,
            value
        );

        return true;
    }


    /*
     * ============================================================
     * ONLY PROCESS NEW ACCEPTANCE
     * ============================================================
     */

    var acceptedValue =
        getChoiceValueByLabel(
            current.getTableName(),
            'response',
            'Accepted'
        );

    if (!acceptedValue) {
        return;
    }

    if (
        !current.response.changesTo(
            acceptedValue
        )
    ) {
        return;
    }


    /*
     * ============================================================
     * PARENT REQUEST
     * ============================================================
     */

    var requestId =
        String(
            current.getValue('request') || ''
        );

    if (!requestId) {
        return;
    }

    var request =
        new GlideRecord(
            'x_snc_campus360_mock_interview_slot_request'
        );

    if (!request.get(requestId)) {
        return;
    }


    /*
     * ============================================================
     * DO NOT PROCESS IF ANOTHER TRAINER ALREADY WON
     * ============================================================
     */

    var acceptedRequestValue =
        getChoiceValueByLabel(
            request.getTableName(),
            'status',
            'Accepted'
        );

    if (
        acceptedRequestValue &&
        String(
            request.getValue('status')
        ) === String(acceptedRequestValue)
    ) {

        var existingTrainer = '';

        if (
            request.isValidField(
                'accepted_trainer'
            )
        ) {

            existingTrainer =
                String(
                    request.getValue(
                        'accepted_trainer'
                    ) || ''
                );
        }

        var thisTrainer = '';

        if (
            current.isValidField('trainer')
        ) {

            thisTrainer =
                String(
                    current.getValue(
                        'trainer'
                    ) || ''
                );
        }

        if (
            existingTrainer &&
            thisTrainer &&
            existingTrainer !== thisTrainer
        ) {
            return;
        }
    }


    /*
     * ============================================================
     * GET AVAILABILITY
     * ============================================================
     */

    var availabilityId = '';

    if (
        request.isValidField(
            'requested_timing'
        ) &&
        request.getValue(
            'requested_timing'
        )
    ) {

        availabilityId =
            String(
                request.getValue(
                    'requested_timing'
                )
            );
    }

    if (
        !availabilityId &&
        request.isValidField(
            'selected_availability'
        ) &&
        request.getValue(
            'selected_availability'
        )
    ) {

        availabilityId =
            String(
                request.getValue(
                    'selected_availability'
                )
            );
    }

    if (!availabilityId) {
        return;
    }


    var availability =
        new GlideRecord(
            'x_snc_campus360_trainer_interview_availability'
        );

    if (!availability.get(
        availabilityId
    )) {
        return;
    }


    /*
     * ============================================================
     * EXACT RAW SLOT VALUES
     * ============================================================
     */

    var dateValue =
        String(
            availability.getValue(
                'available_date'
            ) || ''
        );

    var startValue =
        String(
            availability.getValue(
                'start_time'
            ) || ''
        );

    var endValue =
        String(
            availability.getValue(
                'end_time'
            ) || ''
        );

    var typeValue =
        String(
            availability.getValue(
                'interview_type'
            ) || ''
        );

    var skillValue = '';

    if (
        availability.isValidField(
            'skill_area'
        )
    ) {

        skillValue =
            String(
                availability.getValue(
                    'skill_area'
                ) || ''
            );
    }


    /*
     * ============================================================
     * PARENT REQUEST STATUS
     * ============================================================
     */

    setChoiceByLabel(
        request,
        'status',
        'Accepted'
    );

    if (
        request.isValidField(
            'accepted_trainer'
        ) &&
        current.isValidField('trainer')
    ) {

        request.setValue(
            'accepted_trainer',
            current.getValue(
                'trainer'
            )
        );
    }

    if (
        request.isValidField(
            'accepted_on'
        )
    ) {

        request.setValue(
            'accepted_on',
            new GlideDateTime().getValue()
        );
    }

    /*
     * Keep both references populated.
     */
    if (
        request.isValidField(
            'requested_timing'
        ) &&
        !request.getValue(
            'requested_timing'
        )
    ) {

        request.setValue(
            'requested_timing',
            availabilityId
        );
    }

    if (
        request.isValidField(
            'selected_availability'
        ) &&
        !request.getValue(
            'selected_availability'
        )
    ) {

        request.setValue(
            'selected_availability',
            availabilityId
        );
    }


    /*
     * ============================================================
     * BOOK ALL TRAINERS FOR THE EXACT SLOT
     *
     * Example:
     *
     * TRA0001003  TR001  10:00-11:00  Java
     * TRA0001004  TR002  10:00-11:00  Java
     *
     * Both become Booked.
     * ============================================================
     */

    var availableValue =
        getChoiceValueByLabel(
            availability.getTableName(),
            'status',
            'Available'
        );

    var bookedValue =
        getChoiceValueByLabel(
            availability.getTableName(),
            'status',
            'Booked'
        );

    if (
        availableValue &&
        bookedValue
    ) {

        var allSlots =
            new GlideRecord(
                availability.getTableName()
            );

        allSlots.addQuery(
            'available_date',
            dateValue
        );

        allSlots.addQuery(
            'start_time',
            startValue
        );

        allSlots.addQuery(
            'end_time',
            endValue
        );

        allSlots.addQuery(
            'interview_type',
            typeValue
        );

        if (
            availability.isValidField(
                'skill_area'
            )
        ) {

            allSlots.addQuery(
                'skill_area',
                skillValue
            );
        }

        allSlots.addQuery(
            'active',
            true
        );

        allSlots.addQuery(
            'status',
            availableValue
        );

        allSlots.query();

        while (allSlots.next()) {

            allSlots.setValue(
                'status',
                bookedValue
            );

            allSlots.update();
        }
    }


    /*
     * ============================================================
     * FIND / CREATE MOCK INTERVIEW
     * ============================================================
     */

    var studentId =
        String(
            request.getValue(
                'student'
            ) || ''
        );

    var trainerId = '';

    if (
        current.isValidField(
            'trainer'
        )
    ) {

        trainerId =
            String(
                current.getValue(
                    'trainer'
                ) || ''
            );
    }

    var mock =
        new GlideRecord(
            'x_snc_campus360_mock_interview'
        );

    var existingMockId = '';

    /*
     * First check by slot_request if the field exists.
     */
    if (
        mock.isValidField(
            'slot_request'
        )
    ) {

        mock.addQuery(
            'slot_request',
            request.getUniqueValue()
        );

        mock.setLimit(1);
        mock.query();

        if (mock.next()) {
            existingMockId =
                String(
                    mock.getUniqueValue()
                );
        }
    }


    /*
     * If not found, create it.
     */
    if (!existingMockId) {

        mock.initialize();

        if (
            mock.isValidField(
                'student'
            )
        ) {

            mock.setValue(
                'student',
                studentId
            );
        }

        if (
            mock.isValidField(
                'trainer'
            )
        ) {

            mock.setValue(
                'trainer',
                trainerId
            );
        }

        /*
         * Date field.
         */
        if (
            mock.isValidField(
                'interview_date'
            )
        ) {

            mock.setValue(
                'interview_date',
                dateValue
            );
        }

        /*
         * Time-only fields.
         *
         * IMPORTANT:
         * Do NOT use GlideDateTime here.
         */
        if (
            mock.isValidField(
                'start_time'
            )
        ) {

            mock.setValue(
                'start_time',
                startValue
            );
        }

        if (
            mock.isValidField(
                'end_time'
            )
        ) {

            mock.setValue(
                'end_time',
                endValue
            );
        }

        /*
         * Interview type.
         *
         * Resolve the actual choice value on Mock Interview.
         */
        if (
            mock.isValidField(
                'interview_type'
            )
        ) {

            var mockTypeValue =
                getChoiceValueByLabel(
                    mock.getTableName(),
                    'interview_type',
                    availability.getDisplayValue(
                        'interview_type'
                    )
                );

            if (mockTypeValue) {

                mock.setValue(
                    'interview_type',
                    mockTypeValue
                );

            } else {

                /*
                 * If the Mock Interview field is a reference/
                 * different implementation, do not force it.
                 */
            }
        }

        /*
         * Slot Request reference.
         */
        if (
            mock.isValidField(
                'slot_request'
            )
        ) {

            mock.setValue(
                'slot_request',
                request.getUniqueValue()
            );
        }

        /*
         * Scheduled status if the actual choice exists.
         */
        setChoiceByLabel(
            mock,
            'interview_status',
            'Scheduled'
        );

        setChoiceByLabel(
            mock,
            'attendance_status',
            'Scheduled'
        );

        setChoiceByLabel(
            mock,
            'qr_status',
            'Generated'
        );

        var newMockId =
            mock.insert();

        if (!newMockId) {
            return;
        }

        existingMockId =
            String(newMockId);

        /*
         * Re-load.
         */
        mock =
            new GlideRecord(
                'x_snc_campus360_mock_interview'
            );

        if (!mock.get(
            existingMockId
        )) {
            return;
        }
    }


    /*
     * ============================================================
     * CREATE QR URL
     * ============================================================
     */

    var portalBase =
        String(
            gs.getProperty(
                'glide.servlet.uri'
            ) || ''
        );

    if (
        portalBase &&
        mock.isValidField(
            'qr_url'
        )
    ) {

        var attendanceTarget =
            portalBase +
            'sp?id=qr_attendance&interview_id=' +
            encodeURIComponent(
                existingMockId
            );

        mock.setValue(
            'qr_url',
            attendanceTarget
        );

        /*
         * QR image.
         *
         * If qr_code is a URL/string field this will display
         * correctly in the widget.
         */
        if (
            mock.isValidField(
                'qr_code'
            )
        ) {

            var qrImage =
                'https://api.qrserver.com/v1/create-qr-code/?size=300x300&data=' +
                encodeURIComponent(
                    attendanceTarget
                );

            mock.setValue(
                'qr_code',
                qrImage
            );
        }

        mock.update();
    }


    /*
     * ============================================================
     * LINK MOCK INTERVIEW TO PARENT
     * ============================================================
     */

    if (
        request.isValidField(
            'mock_interview'
        )
    ) {

        request.setValue(
            'mock_interview',
            existingMockId
        );
    }

    request.update();


    /*
     * ============================================================
     * STUDENT NOTIFICATION
     * ============================================================
     */

    var notification =
        new GlideRecord(
            'x_snc_campus360_student_notification'
        );

    /*
     * Avoid duplicate notification.
     */
    var duplicateNotification = false;

    if (
        notification.isValidField(
            'student'
        )
    ) {

        notification.addQuery(
            'student',
            studentId
        );

        if (
            notification.isValidField(
                'message'
            )
        ) {

            notification.addQuery(
                'message',
                'CONTAINS',
                String(
                    request.getDisplayValue()
                )
            );
        }

        notification.setLimit(1);
        notification.query();

        if (notification.next()) {
            duplicateNotification = true;
        }
    }


    if (!duplicateNotification) {

        notification.initialize();

        if (
            notification.isValidField(
                'student'
            )
        ) {

            notification.setValue(
                'student',
                studentId
            );
        }

        if (
            notification.isValidField(
                'message'
            )
        ) {

            notification.setValue(
                'message',
                'Your mock interview has been confirmed for ' +
                dateValue +
                ' from ' +
                startValue +
                ' to ' +
                endValue +
                '. Trainer: ' +
                String(
                    current.getDisplayValue(
                        'trainer'
                    ) || ''
                ) +
                '.'
            );
        }

        if (
            notification.isValidField(
                'sent_date'
            )
        ) {

            notification.setValue(
                'sent_date',
                new GlideDateTime().getValue()
            );
        }

        if (
            notification.isValidField(
                'action_required'
            )
        ) {

            notification.setValue(
                'action_required',
                false
            );
        }

        if (
            notification.isValidField(
                'action_taken'
            )
        ) {

            notification.setValue(
                'action_taken',
                false
            );
        }

        if (
            notification.isValidField(
                'reminder_count'
            )
        ) {

            notification.setValue(
                'reminder_count',
                0
            );
        }

        /*
         * Use real choices if they exist.
         */
        setChoiceByLabel(
            notification,
            'notification_type',
            'Mock Interview'
        );

        if (
            !notification.getValue(
                'notification_type'
            )
        ) {

            setChoiceByLabel(
                notification,
                'notification_type',
                'Interview'
            );
        }

        setChoiceByLabel(
            notification,
            'status',
            'Unread'
        );

        if (
            !notification.getValue(
                'status'
            )
        ) {

            setChoiceByLabel(
                notification,
                'status',
                'New'
            );
        }

        /*
         * DO NOT set notification_id.
         * Let ServiceNow generate it.
         */
        notification.insert();
    }


})(current, previous);
